-- auto-apply
-- Reporter lineup (owner 2026-10-31). Reporters are being grown as an idol-style IP
-- (photocards, goods), so names that match real celebrities are replaced (정우성 → 서도윤,
-- 한소희 → 송유나, 김지원 → 한다온, 박서진 → 이리안), the politics beat goes, beats follow
-- the sections that actually have articles, and every reporter gets fan-profile fields
-- (age, birthday MM-DD, mbti, symbol, catchphrase, likes; *_en for learners). cr2 becomes a
-- human rookie (art pending), cr8 stays the fennec mascot (art pending), 앨리샤 keeps her
-- look and gets her birthday (12-14). Images are untouched. Text goes in as base64 so the
-- query API can't mangle Hangul. Idempotent: fixed values, safe to re-run.
do $$
begin
  if to_regclass('public.character_reporters') is null then return; end if;
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr5';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr1';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr7';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr6';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr9';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr10';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr3';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr4';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr2';
  update public.character_reporters set data = data || convert_from(decode('', 'base64'), 'UTF8')::jsonb, updated_at = now() where id = 'cr8';
end $$;

-- Articles follow the beats: each section has one reporter (unassigned ones included).
do $$
begin
  if to_regclass('public.articles') is null then return; end if;
  update public.articles a set reporter_id = m.rid
    from (values
      (convert_from(decode('7IKs7ZqM', 'base64'), 'UTF8'), 'cr5'),
      (convert_from(decode('6rWt7KCc', 'base64'), 'UTF8'), 'cr9'),
      (convert_from(decode('66y47ZmU', 'base64'), 'UTF8'), 'cr10'),
      (convert_from(decode('YnV6eg==', 'base64'), 'UTF8'), 'cr10'),
      (convert_from(decode('7Jet7IKs', 'base64'), 'UTF8'), 'cr7'),
      (convert_from(decode('bmF0dXJl', 'base64'), 'UTF8'), 'cr1'),
      (convert_from(decode('dHJhdmVs', 'base64'), 'UTF8'), 'cr1'),
      (convert_from(decode('SVTqs7ztlZk=', 'base64'), 'UTF8'), 'cr6'),
      (convert_from(decode('Sy1wb3A=', 'base64'), 'UTF8'), 'cr4'),
      (convert_from(decode('7Jew7JiI', 'base64'), 'UTF8'), 'cr4'),
      (convert_from(decode('YmVhdXR5', 'base64'), 'UTF8'), 'cr4'),
      (convert_from(decode('S29yZWE=', 'base64'), 'UTF8'), 'cr2'),
      (convert_from(decode('7Jik7ZS864uI7Ja4', 'base64'), 'UTF8'), 'cr3'),
      (convert_from(decode('6rK97KCc', 'base64'), 'UTF8'), 'cr3')
    ) as m(sec, rid)
   where a.section = m.sec and a.reporter_id is distinct from m.rid;
end $$;
